#include <iostream>
#include <vector>

int main() {
    std::vector<int> v{1, 3, 5, 7, 9};
    int lo = 0, hi = 4, target = 7, found = -1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (v[mid] == target) { found = mid; break; }
        if (v[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    std::cout << found << "\n";
    return 0;
}

